/**
 * End-to-end conformance with the Python verifier: every case of the backend's
 * tests/vectors/levels_v1.json must give the same status and the same failed checks, using the
 * ledger dump of that file (test data generated by make_vectors.py, never shown as real).
 */
import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import {
  type Crop, type Ledger, type Recipe, type TrustList, type TxInfo, LedgerUnavailable, MemoryLedger, isClassicAddress, parseManifest, parseTrustList, applyRecipe, ascii, bitmapToSet, deriveLevel,
  parseSidecarText, readPng, readSidecar, setToBitmap, sha256, sidecarJson, toHex, verifyLevel, withAnchor, writePng,
} from '../../lib/velum'

const L = JSON.parse(readFileSync(new URL('../../../tests/vectors/levels_v1.json', import.meta.url), 'utf8'))
const b64 = (s: string) => new Uint8Array(Buffer.from(s, 'base64'))
const png = (sha: string | null) => (sha === null ? null : b64(L.png_files[sha]))
const STATUS = { verified: 'ACCEPT', rejected: 'REJECT', unknown: 'UNVERIFIABLE' } as const

const txs: TxInfo[] = Object.entries(L.ledger as Record<string, any>).map(([hash, t]) => ({
  hash,
  validated: t.validated,
  result: t.result,
  account: t.account,
  type: t.tx_type,
  memos: t.memos.map(([type, data]: [string, string]) => ({ type: toHex(ascii(type)), data: data.toLowerCase() })),
  ledgerIndex: t.ledger_index,
  closeTimeIso: new Date(t.close_time * 1000).toISOString().replace('.000Z', 'Z'),
}))
const trust = (name: string): TrustList => parseTrustList({ version: 'vectors', entries: L.trust_lists[name] })
const down: Ledger = { label: 'down', network: 'testnet', getTx: async () => { throw new LedgerUnavailable('vector case: ledger down') } }

describe('levels_v1: same verdict and failed checks as the Python verifier', () => {
  for (const c of L.cases) {
    it(c.name, async () => {
      const sha = (b: Uint8Array) => toHex(sha256(b))
      const evidence = png(c.evidence_png)!
      expect(sha(evidence)).toBe(c.evidence_png)
      const r = await verifyLevel(
        { evidence, sidecar: c.sidecar, rendition: png(c.rendition_png) },
        { trustList: trust(c.trust), ledger: c.ledger === 'down' ? down : new MemoryLedger(txs) },
      )
      expect(STATUS[r.verdict]).toBe(c.expected_status)
      expect(r.checks.filter((k) => k.state === 'fail').map((k) => k.id)).toEqual(c.expected_failed)
      expect(r.checks.filter((k) => k.state === 'unknown').map((k) => k.id)).toEqual(c.expected_unknown)
    })
  }
})

describe('a ledger that cannot answer is UNVERIFIABLE, never REJECT', () => {
  it('L0 with an unreachable ledger', async () => {
    const c = L.cases[0]
    const r = await verifyLevel({ evidence: png(c.evidence_png)!, sidecar: c.sidecar }, {
      trustList: trust(c.trust),
      ledger: { label: 'down', network: 'testnet', getTx: async () => { const { LedgerUnavailable } = await import('../../lib/velum'); throw new LedgerUnavailable('offline') } },
    })
    expect(r.verdict).toBe('unknown')
    expect(r.checks.filter((k) => k.state === 'fail')).toEqual([])
  })
  it('over-budget evidence keeps V6 inconclusive, unless the rendition cannot be read', async () => {
    const c = L.cases.find((x: { rendition_png: string | null; expected_status: string }) => x.rendition_png && x.expected_status === 'ACCEPT')
    const opts = { trustList: trust(c.trust), ledger: new MemoryLedger(txs), maxPixels: 10_000 }
    let r = await verifyLevel({ evidence: png(c.evidence_png)!, sidecar: c.sidecar, rendition: png(c.rendition_png) }, opts)
    expect(r.verdict).toBe('unknown')
    expect(r.checks.filter((k) => k.state === 'unknown').map((k) => k.id)).toEqual(['V3', 'V6'])
    r = await verifyLevel({ evidence: png(c.evidence_png)!, sidecar: c.sidecar, rendition: ascii('invalid PNG') }, opts)
    expect(r.verdict).toBe('rejected')
    expect(r.checks.find((k) => k.id === 'V6')!.state).toBe('fail')
  })
  it('a second embedded sidecar is refused before it is inflated', async () => {
    const { writePng: write, makeImage } = await import('../../lib/velum')
    const one = write(makeImage(1, 1, new Uint8Array(3)), '')
    const crc = (await import('../../lib/velum')).crc32
    const body = ascii('velum.sidecar\0\0invalid')
    const type = ascii('zTXt')
    const len = new Uint8Array(4); new DataView(len.buffer).setUint32(0, body.length)
    const sum = new Uint8Array(4); new DataView(sum.buffer).setUint32(0, crc(type, body))
    const pos = Buffer.from(one).indexOf('IDAT') - 4
    const two = new Uint8Array([...one.subarray(0, pos), ...len, ...type, ...body, ...sum, ...one.subarray(pos)])
    await expect(readSidecar(two)).rejects.toThrow(/more than one/)
  })
  it('an image above the pixel budget', async () => {
    const c = L.cases[0]
    const r = await verifyLevel({ evidence: png(c.evidence_png)!, sidecar: c.sidecar }, { trustList: trust(c.trust), ledger: new MemoryLedger(txs), maxPixels: 16 })
    expect(r.verdict).toBe('unknown')
    expect(r.checks.find((k) => k.id === 'V3')!.state).toBe('unknown')
  })
  it('an image above the pixel budget, with a rendition', async () => {
    const c = L.cases.find((x: { rendition_png: string | null, expected_status: string }) => x.rendition_png && x.expected_status === 'ACCEPT')
    const r = await verifyLevel({ evidence: png(c.evidence_png)!, sidecar: c.sidecar, rendition: png(c.rendition_png) },
      { trustList: trust(c.trust), ledger: new MemoryLedger(txs), maxPixels: 16 })
    expect(r.verdict).toBe('unknown')
    expect(r.checks.filter((k) => k.state === 'fail')).toEqual([])
    expect(r.checks.find((k) => k.id === 'V6')!.state).toBe('unknown')
  })
})

describe('recipe vectors', () => {
  for (const c of L.recipe) {
    it(c.name, async () => {
      const out = applyRecipe(await readPng(b64(c.input_png_b64)), c.crop as Crop | null, c.recipe as Recipe | null)
      const want = await readPng(b64(c.output_png_b64))
      expect([out.width, out.height]).toEqual([want.width, want.height])
      expect(toHex(sha256(out.rgb))).toBe(toHex(sha256(want.rgb)))
    })
  }
})

describe('hidden bitmap', () => {
  for (const c of L.bitmap) {
    it(`n = ${c.n}`, () => {
      expect(setToBitmap(new Set(c.hidden), c.n)).toBe(c.hex)
      expect([...bitmapToSet(c.hex, c.n)].sort((a, b) => a - b)).toEqual(c.hidden)
    })
  }
})

describe('the Editor path: derive, anchor, embed, verify', () => {
  it('sidecarJson writes the same bytes as the Python Sidecar.to_text()', () => {
    for (const c of L.cases.filter((x: { sidecar: string | null }) => x.sidecar && x.sidecar.includes('"level_tx"'))) {
      let sc
      try {
        sc = parseSidecarText(c.sidecar)
      } catch {
        continue // the hostile cases
      }
      expect(sidecarJson(sc)).toBe(c.sidecar)
    }
  })
  it('a copy derived in JS from a vector level verifies once its descriptor is on the ledger', async () => {
    const c = L.cases.find((x: { name: string }) => x.name.startsWith('L1 lab, tile 5'))
    const evidencePng = png(c.evidence_png)!
    const source = parseSidecarText((await readSidecar(evidencePng)) ?? c.sidecar)
    const lv = deriveLevel({ source, evidence: await readPng(evidencePng), hide: [0], crop: null, recipe: null, producer: source.level.producer })
    expect(lv.added).toEqual([0])
    // the anchor the wallet would send: a test transaction from the same producer, in a later ledger
    const { descriptorHash } = await import('../../lib/velum')
    const anchor: TxInfo = {
      hash: 'F'.repeat(64), validated: true, result: 'tesSUCCESS', account: lv.descriptor.producer, type: 'AccountSet',
      memos: [{ type: toHex(ascii('velum/level')), data: descriptorHash(lv.descriptor) }], ledgerIndex: 999999, closeTimeIso: '2027-01-01T00:00:00Z',
    }
    const text = sidecarJson(withAnchor(lv, anchor.hash))
    expect(parseSidecarText(text).level_tx).toBe(anchor.hash)
    const r = await verifyLevel({ evidence: writePng(lv.evidence, text) }, { trustList: trust(c.trust), ledger: new MemoryLedger([...txs, anchor]) })
    expect(r.sidecarSource).toBe('embedded')
    expect(r.checks.filter((k) => k.state !== 'pass' && k.state !== 'skipped').map((k) => `${k.id}: ${k.reasons.join('; ')}`)).toEqual([])
    expect(r.verdict).toBe('verified')
  })
})

describe('addresses and trust lists are parsed as strictly as in Python', () => {
  const entry = L.trust_lists.default[0]
  it('a classic address needs a valid checksum', () => {
    expect(isClassicAddress(entry.xrpl_address)).toBe(true)
    expect(isClassicAddress('rPT1Sjq2YGrBMTttX4GZHjKu9dyfzbpAYe')).toBe(true) // xrpl.js documentation address
    expect(isClassicAddress('rPT1Sjq2YGrBMTttX4GZHjKu9dyfzbpAYf')).toBe(false) // one character changed
    expect(isClassicAddress('xPT1Sjq2YGrBMTttX4GZHjKu9dyfzbpAYe')).toBe(false)
  })
  it('refuses duplicate entries, accepts key rotation and other networks', () => {
    const list = (...entries: object[]) => ({ version: 't', entries })
    expect(() => parseTrustList(list(entry, { ...entry, not_after: '2027-12-31T23:59:59Z' }))).toThrow(/duplicate/)
    expect(parseTrustList(list({ ...entry, network: 'mainnet' }, entry, { ...entry, mldsa44_pk_sha256: 'cd'.repeat(32) })).entries).toHaveLength(3)
    expect(() => parseTrustList(list({ ...entry, not_after: '2027-1-1T1:1:1Z' }))).toThrow(/not_after/)
    expect(() => parseTrustList(list({ ...entry, extra: 1 }))).toThrow(/keys/)
  })
  it('a manifest above 2^25 pixels is invalid even when each side is allowed (manifest.py)', () => {
    const m = JSON.parse(L.cases[0].sidecar).manifest
    expect(() => parseManifest({ ...m, w: 8192, h: 4096 })).not.toThrow() // exactly 2^25
    expect(() => parseManifest({ ...m, w: 8192, h: 4097 })).toThrow(/pixels/)
  })
  it('the shipped trust-list.json is valid', async () => {
    const shipped = JSON.parse(readFileSync(new URL('../../trust-list.json', import.meta.url), 'utf8'))
    expect(parseTrustList(shipped).entries.length).toBeGreaterThan(0)
  })
})
